import { Campaign } from '@/entities/Campaign';

// A simple flag to prevent multiple requests at the same time.
let isLoadingCampaign = false;

/**
 * Fetches the current weekly campaign stages from the database.
 * This function no longer generates the campaign; it only retrieves it.
 * The campaign is expected to be generated by a scheduled backend function.
 * @returns {Promise<Array>} A promise that resolves to an array of campaign stages.
 */
export const loadCampaign = async () => {
  if (isLoadingCampaign) {
    console.log("Campaign is already being loaded.");
    return [];
  }

  isLoadingCampaign = true;
  try {
    console.log("Fetching campaign stages from the database...");
    const stages = await Campaign.list();
    // Ensure stages are sorted correctly by their stage number
    return stages.sort((a, b) => a.stageNumber - b.stageNumber);
  } catch (error) {
    console.error("Error fetching campaign stages:", error);
    return []; // Return empty array on error
  } finally {
    isLoadingCampaign = false;
  }
};